/* ═══════════════════════════════════════════════════════════
   问题池：把「玩家实际扣下的牌」翻译成人话。
   第五幕的问题清单、第六幕的质控意见都由它生成——
   你做过什么，剧本就认什么。加牌只需在这里登记。
   ═══════════════════════════════════════════════════════════ */
var NS_POOL = [
  { label:"未更正错报没有处理干净", cards:["ms2"] },
  { label:"关联方交易 6400 万的披露不充分", cards:["rp","rp2"] },
  { label:"存货跌价 1800 万没有测算", cards:["inv","inv2"] },
  { label:"在建工程晚转固、试运行收支未重分类", cards:["cip","cip2"] },
  { label:"寄售收入提前确认", cards:["consign","consign2"] },
  { label:"德昌破产的应收减值没有调整", cards:["subseq2","subseq3"] },
  { label:"鑫达的问题发票没有查到底", cards:["fraud3","fraud4"] },
  { label:"存货监盘证据只有客户的照片", cards:["stock"] },
  { label:"持续经营评估只有一纸承诺", cards:["going2"] },
  { label:"成本倒轧表始终是空的", cards:["cost"] },
  { label:"低价承接留下的程序缺口", cards:["lowfee"] },
  { label:"被平均砍掉的细节测试", cards:["cut","cut2","later"] },
  { label:"一次没有及时认的错", cards:["wrongcall"] },
  { label:"王磊说的那些话没有访谈记录", cards:["wangtalk","wangtalk2"] },
  { label:"给保荐机构的答复与底稿对不上", cards:["reply"] },
  { label:"成本数据没有来源记录", cards:["zhaobook2"] },
  { label:"离职前的底稿没有重做复核", cards:["resign"] },
  { label:"报告被用于融资，没有跟进", cards:["use2"] }
];

var NS_GOOD = [
  ["stock2","存货监盘（含权属核查）"],
  ["fraud2","问题发票的扩大程序"],
  ["going","持续经营评估"],
  ["subseq","德昌的期后处理"],
  ["occupy","资金占用清理"],
  ["cutoff","截止测试"],
  ["conf","函证的替代程序"],
  ["floor","退货台账追查"],
  ["walk","穿行测试"],
  ["memo","风险备忘录"],
  ["memo2","内部备忘录"],
  ["kam","关键审计事项"],
  ["ms","未更正错报汇总"],
  ["pr1","质控重大项补做"],
  ["pr3","追加预算补程序"],
  ["govletter","治理层书面沟通"],
  ["pre","质控预审整改"],
  ["arch","真实的归档日期"],
  ["sched","签字的资料表"],
  ["revisit","当年底稿的复盘"],
  ["zhouplan","三条与替代方案"],
  ["inquiry","问询函的如实答复"],
  ["zhaobook","成本的两套数"],
  ["use","报告用途的跟进"],
  ["case","写进案例库的复盘"]
];

function NS_hasCards(S, ids){
  var c = (S && S.cards) || [];
  for(var i=0;i<c.length;i++){ if(ids.indexOf(c[i].id)>=0) return true; }
  return false;
}
/* 只算「真扣下的牌」：severity>=1 视为未解决，severity=0 视为做实了的程序 */
function NS_unresolved(S){
  var out=[], c=(S&&S.cards)||[];
  for(var i=0;i<NS_POOL.length;i++){
    for(var j=0;j<c.length;j++){
      if(c[j].severity>=1 && NS_POOL[i].cards.indexOf(c[j].id)>=0){ out.push(NS_POOL[i].label); break; }
    }
  }
  return out;
}
function NS_solved(S){
  var map={}, out=[], c=(S&&S.cards)||[];
  for(var i=0;i<NS_GOOD.length;i++) map[NS_GOOD[i][0]]=NS_GOOD[i][1];
  for(var j=0;j<c.length;j++){
    if(c[j].severity===0 && map[c[j].id] && out.indexOf(map[c[j].id])<0) out.push(map[c[j].id]);
  }
  return out;
}

