/* ─────────────────────────────────────────────
事件字段：
  act        幕号 1-6
  order      幕内顺序
  time       显示在标题上方的时间地点
  title      标题
  text       正文段落数组，支持 <em> 高亮
  talk       { who, lines[] } 可选，人物对话
  cond(S)    可选，返回 false 则该事件不出现
  choices[]  选项，每个含：
    t        选项文字
    sub      副标题（灰色小字，可选）
    eff      资源变化 {hours, morale, client, partner, risk, ms}
    cards[]  扣下的牌 {id,label,trigger,severity,reveal,eff}
    flag     设置标记（可选）
    punish   踩线计数（可选）
    res      选择后的结果叙述
    note     底稿批注（支持 HTML）
───────────────────────────────────────────── */



(function(){
"use strict";
var LS="auditer_save_v1", SLOT_PREFIX="auditer_slot_";
var S=null, LIST=null, SNAP=null, FIRED=[];

function $(id){return document.getElementById(id);}
function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}

/* ═══ 头像与场景背景 ═══ */
function avatarOf(id){
  if(id==="self") return DATA.selfAvatar||"";
  var c=(S&&S.crew[id])||DATA.crew[id];
  return (c&&c.avatar)||"";
}
function avatarImg(id,cls){
  var src=avatarOf(id); if(!src) return "";
  return '<img class="av '+(cls||"")+'" src="'+src+'" alt="" onerror="this.style.visibility=\'hidden\'">';
}
function crewIdByName(who){
  if(!who) return "";
  for(var k in DATA.crew){
    if(!DATA.crew.hasOwnProperty(k)) continue;
    var n=DATA.crew[k].name;
    if(who.indexOf(n)>=0||n.indexOf(who)>=0) return k;
  }
  return "";
}
function actBg(){
  var a=actInfo(S.act);
  return a.bg||"";
}
function setBg(){
  var el=$("bgfx"); if(!el) return;
  var u=actBg(); if(!u) return;
  if(el.getAttribute("data-bg")!==u){ el.setAttribute("data-bg",u); el.style.backgroundImage='url("'+u+'")'; }
}

function initCrew(){
  var o={};
  for(var k in DATA.crew){
    if(!DATA.crew.hasOwnProperty(k)) continue;
    var c=DATA.crew[k], n={};
    for(var p in c){ if(c.hasOwnProperty(p)) n[p]=c[p]; }
    n.id=k; n.met=false; o[k]=n;
  }
  if(o.zhou) o.zhou.met=true;
  return o;
}

function fresh(){
  return {act:1,i:0,screen:"title",hours:1300,max:1300,morale:80,client:68,partner:58,risk:0,
          cards:[],flags:{},log:[],ms:0,decisions:0,punish:0,
          crew:initCrew(),pick:{},dispatchDone:false,newMeet:[],
          truth:[],health:70,ccOn:false,seenSig:[],newAch:[]};
}

/* ═══════ 存储层：本机不可写时退回内存，并且永不静默失败 ═══════ */
var MEM={};
var STORE_OK=(function(){
  try{ localStorage.setItem("__auditer_t","1"); localStorage.removeItem("__auditer_t"); return true; }
  catch(e){ return false; }
})();
function sget(k){ try{ return STORE_OK? localStorage.getItem(k) : (MEM[k]||null); }catch(e){ return MEM[k]||null; } }
function sset(k,v){ try{ if(STORE_OK) localStorage.setItem(k,v); else MEM[k]=v; }catch(e){ MEM[k]=v; } }
function sdel(k){ try{ if(STORE_OK) localStorage.removeItem(k); else delete MEM[k]; }catch(e){ delete MEM[k]; } }

function slotKey(n){ return n==="auto" ? LS : (SLOT_PREFIX+n); }
function slotRead(n){
  var raw=sget(slotKey(n)); if(!raw) return null;
  try{ var o=JSON.parse(raw); return (o && o.act) ? o : null; }catch(e){ return null; }
}
function slotWrite(n,state){
  var o=JSON.parse(JSON.stringify(state)); o.ts=Date.now(); o.slot=n;
  sset(slotKey(n), JSON.stringify(o));
}
function slotDel(n){ sdel(slotKey(n)); }
function save(){
  if(S && S.screen==="saves"){ markSaved(); return; }   /* 存档界面不覆盖自动存档 */
  if(S && S.screen!=="title"){
    try{ S.pv=(LIST && LIST[S.i] && LIST[S.i].title) || (actInfo(S.act).name+"阶段"); }catch(e){}
    S.ts=Date.now();
  }
  sset(LS,JSON.stringify(S));
  markSaved();
}
function load(){
  try{
    var raw=sget(LS); if(!raw) return null;
    var o=JSON.parse(raw); if(!o || !o.act) return null; return o;
  }catch(e){ return null; }
}
function markSaved(){
  var el=$("saveInd"); if(!el) return;
  if(!STORE_OK){
    el.className="save-ind warn";
    el.innerHTML='<i></i><span>本机不可写入 · 请用导出</span>';
    return;
  }
  el.className="save-ind";
  el.innerHTML='<i></i><span>已自动保存</span>';
}

function actInfo(n){
  for(var i=0;i<DATA.acts.length;i++){ if(DATA.acts[i].n===n) return DATA.acts[i]; }
  return {n:n,name:"",sub:"",quote:""};
}

function buildList(){
  var arr=[];
  for(var i=0;i<DATA.events.length;i++){
    var e=DATA.events[i];
    if(e.act!==S.act) continue;
    if(e.cond && !e.cond(S)) continue;
    arr.push(e);
  }
  arr.sort(function(a,b){return (a.order||0)-(b.order||0);});
  LIST=arr;
}

function riskLevel(r){
  if(r<18) return {t:"干净",c:"#2B6B57",h:"该做的程序都做了，底稿经得起翻"};
  if(r<38) return {t:"有些欠账",c:"#7C8A2E",h:"有几页是你自己也不太想回看的"};
  if(r<58) return {t:"不太稳",c:"#9A6F32",h:"质控要是挑这几处，你没多少话好说"};
  if(r<78) return {t:"高危",c:"#B4593B",h:"欠的东西已经不是技术问题了"};
  return {t:"随时会炸",c:"#8F3327",h:"你在等一个时间点，不是等一个理由"};
}

function renderSteps(){
  var h="";
  for(var i=1;i<=6;i++){
    var cls = i<S.act ? "on" : (i===S.act ? "cur" : "");
    h+='<i class="'+cls+'"></i>';
  }
  $("steps").innerHTML=h;
}

function moodText(m){
  if(m>=70) return "状态还好";
  if(m>=45) return "有点累";
  if(m>=25) return "快撑不住";
  return "随时会散";
}
function pv(label,val,warn,unk){
  if(unk) return '<span class="p-row"><span>'+label+'</span><b class="unk">?</b></span>';
  return '<span class="p-row"><span>'+label+'</span><b class="'+(warn?'low':'')+'">'+val+'</b></span>';
}
function personCard(id){
  var c=S.crew[id];
  if(!c||!c.met) return "";
  if(id==="zhou") c.trust=S.partner;
  if(id==="li") c.coop=S.client;
  var h='<div class="pcard">';
  h+='<div class="p-top"><span class="p-name">'+esc(c.name)+'</span><span class="p-role">'+esc(c.role)+'</span></div>';
  h+='<div class="p-rows">';
  h+=pv("信任",c.trust,c.trust<30);
  if(c.energy!=null) h+=pv("精力",c.energy,c.energy<35);
  if(c.skill!=null) h+=pv("能力",c.skill,false,!c.skillKnown);
  if(c.patience!=null) h+=pv("耐心",c.patience,c.patience<30);
  if(c.coop!=null) h+=pv("配合",c.coop,c.coop<35);
  h+='</div>';
  if(c.energy!=null) h+='<div class="p-mini"><i class="'+(c.energy<35?'warn':'')+'" style="width:'+clamp(c.energy,0,100)+'%"></i></div>';
  h+='<div class="p-note">'+esc(c.note)+'</div>';
  h+='</div>';
  return h;
}
function crewGroup(title,ids,mood){
  var cards="";
  for(var i=0;i<ids.length;i++) cards+=personCard(ids[i]);
  if(!cards) return "";
  return '<div class="panel-hd grp"><span>'+title+'</span>'+(mood?'<span class="grp-tag">'+moodText(S.morale)+'</span>':'')+'</div>'+cards;
}

function pgauge(v,label,word){
  var col=v<35?"#B4593B":(v<65?"#C9A96B":"#1D9E75");
  return '<div class="pg" title="'+label+' '+v+' · '+word+'"><i style="width:'+clamp(v,0,100)+'%;background:'+col+'"></i></div>';
}
function trustWord(v){return v<35?"对你有戒心":(v<50?"有所保留":(v<65?"还算配合":(v<80?"信任你":"很信任你")));}
function stateWord(v,c){
  if(c.coop!=null&&c.energy==null&&c.patience==null) return v<35?"不太配合":(v<50?"有所保留":(v<65?"还算配合":"很配合"));
  return v<35?"快撑不住了":(v<50?"有些疲惫":(v<65?"状态尚可":"状态不错"));
}
function stateLabel(c){return (c.coop!=null&&c.energy==null&&c.patience==null)?"配合度":"状态";}
function skillWord(v){return v<35?"还在学":(v<50?"能打下手":(v<65?"可以独立做":"很可靠"));}
function personRow(id){
  var c=S.crew[id];
  if(!c||!c.met) return "";
  if(id==="zhou") c.trust=S.partner;
  if(id==="li") c.coop=S.client;
  var v1=c.trust;
  var v2=(c.energy!=null)?c.energy:((c.patience!=null)?c.patience:((c.coop!=null)?c.coop:null));
  var v3=(c.skill!=null)?(c.skillKnown?c.skill:"?"):null;
  var ar="";
  if(S.crewDelta && S.crewDelta[id]) ar='<i class="ar '+(S.crewDelta[id]>0?"up":"dn")+'">'+(S.crewDelta[id]>0?"▲":"▼")+'</i>';
  var h='<div class="prow" title="'+esc(c.note)+'">';
  h+=avatarImg(id,"pr-av");
  h+='<div class="pnm">'+esc(c.name)+ar+'<em>'+esc(String(c.role).split(" · ")[0])+'</em></div>';
  h+=pgauge(v1,"信任",trustWord(v1));
  h+=(v2==null)?'<div></div>':pgauge(v2,stateLabel(c),stateWord(v2,c));
  if(v3==null) h+='<div></div>';
  else if(v3==="?") h+='<div class="pg pg-unknown" title="能力 · 还不了解，派次活看看就知道"></div>';
  else h+=pgauge(v3,"能力",skillWord(v3));
  h+='</div>';
  return h;
}
function crewGroup(title,ids,tags){
  var rows="";
  for(var i=0;i<ids.length;i++) rows+=personRow(ids[i]);
  if(!rows) return "";
  var h='<div class="prow grp-hd" title="三个小条依次为：信任 / 状态(配合度·精力) / 能力。绿色=不错，土黄=一般，砖红=偏低；鼠标放在小条上可看具体说法。"><span class="g-title">'+title+'</span>';
  for(var j=0;j<3;j++) h+='<span>'+(tags[j]||"")+'</span>';
  return h+'</div>'+rows;
}

function renderPanel(){
  var r=riskLevel(S.risk);
  var hp=Math.round(S.hours/S.max*100);
  var h="";
  h+='<div class="panel-hd">项 目</div>';
  var htxt = S.hours<=0 ? '<b style="color:#8F3327;font-size:12px">已超支</b>' : '<b class="mono">'+S.hours+'h</b>';
  h+='<div class="gauge tight"><div class="hd"><span>预算工时</span>'+htxt+'</div><div class="bar '+(hp<25?"r":"g")+'"><i style="width:'+clamp(hp,0,100)+'%"></i></div></div>';
  h+='<div class="gauge tight"><div class="hd"><span>风险欠账</span><b class="risk-txt" style="color:'+r.c+'">'+r.t+'</b></div><div class="bar r"><i style="width:'+clamp(S.risk,0,100)+'%;background:'+r.c+'"></i></div><p class="risk-hint">'+r.h+'</p></div>';
  var cs=companyState();
  h+='<div class="coh" title="'+esc(cs.h)+'"><span>HX 现状</span><b>'+esc(cs.t)+'</b></div>';
  h+=crewGroup("所 内",["zhou","xu","lin"],["信","态","能"]);
  h+=crewGroup("客 户 方",["li","wang","zhao"],["信","态",""]);
  if(S.cards.length){
    h+='<div class="cards-box"><div class="hd"><span>扣下的牌</span><b>'+S.cards.length+'</b></div>';
    var startAt=Math.max(0,S.cards.length-4);
    if(startAt>0) h+='<span class="chip more">更早的 '+startAt+' 件</span>';
    for(var i=startAt;i<S.cards.length;i++){ h+='<span class="chip">'+esc(S.cards[i].label||"未决事项")+'</span>'; }
    h+='</div>';
  }
  $("panel").innerHTML=h;
}

function render(){
  document.body.classList.toggle("solo", S.screen==="title"||S.screen==="actIntro"||S.screen==="ending"||S.screen==="saves"||S.screen==="ach");
  document.body.classList.toggle("center", S.screen==="title"||S.screen==="actIntro");
  setBg();
  renderSteps();
  if(S.screen==="title"){ $("panel").innerHTML=""; renderTitle(); $("steps").innerHTML=""; return; }
  if(S.screen==="saves"){ $("panel").innerHTML=""; $("stage").innerHTML=viewSaves(); return; }
  if(S.screen==="ach"){ $("panel").innerHTML=""; $("stage").innerHTML=viewAch(); return; }
  renderPanel();
  var st=$("stage");
  if(S.screen==="actIntro") st.innerHTML=viewActIntro();
  else if(S.screen==="event") st.innerHTML=viewEvent();
  else if(S.screen==="say"){ if(S.pending==null){ S.screen="event"; st.innerHTML=viewEvent(); } else { st.innerHTML=viewSay(); } }
  else if(S.screen==="result") st.innerHTML=viewResult();
  else if(S.screen==="dispatch") st.innerHTML=viewDispatch();
  else if(S.screen==="dispatchResult") st.innerHTML=viewDispatchResult();
  else if(S.screen==="actEnd") st.innerHTML=viewActEnd();
  else if(S.screen==="ach") st.innerHTML=viewAch();
  else if(S.screen==="ending") st.innerHTML=viewEnding();
  st.classList.remove("fade"); void st.offsetWidth; st.classList.add("fade");
  window.scrollTo({top:0,behavior:"smooth"});
}

function renderTitle(){
  var sv=load();
  var h='<div class="title-screen">';
  if(DATA.acts[0]&&DATA.acts[0].bg){
    h+='<div class="act-hero slim"><img src="'+DATA.acts[0].bg+'" alt="" onerror="this.parentNode.style.display=\'none\'"><div class="ah-ov"></div></div>';
  }
  h+='<div class="kicker">AUDITER · 一 个 项 目 经 理 的 九 十 天</div>';
  h+='<h1>AUDITER</h1>';
  h+='<div class="sub">一个项目经理的 90 天</div>';
  h+='<div class="lead">';
  h+='<p>你升上项目经理的第一年。第一个完整项目，交到你手上。</p>';
  h+='<p>预算不够、客户着急、人都派出去了。你可以省一点，也可以硬一点。账总能平，风险不会。</p>';
  h+='<p>它只是会晚一点到，由别人来问。</p>';
  h+='</div>';
  h+='<button class="btn-primary" data-act="start">开始这一年</button>';
  if(sv) h+='<button class="btn-ghost" data-act="resume">继续上次</button>';
  h+='<button class="btn-ghost" data-act="saves">存档管理</button>';
  h+='<button class="btn-ghost" data-act="ach">成就 '+achCount()+'</button>';
  h+='<div class="meta">六幕 · 61 个现场事件 · 八个结局<br>纯本地运行，不联网，进度自动存在本机</div>';
  h+='</div>';
  $("stage").innerHTML=h;
}

/* ═══════ 存档界面 ═══════ */
function fmtTime(ts){
  if(!ts) return "";
  var d=new Date(ts), p=function(n){ return n<10?("0"+n):(""+n); };
  return d.getFullYear()+"-"+p(d.getMonth()+1)+"-"+p(d.getDate())+" "+p(d.getHours())+":"+p(d.getMinutes());
}
function slotName(n){ return n==="auto" ? "自动" : ("存档 "+n); }
function slotList(){
  var out=[{n:"auto",data:slotRead("auto")}];
  for(var i=1;i<=3;i++) out.push({n:i,data:slotRead(i)});
  return out;
}
function slotCard(x){
  var d=x.data, n=x.n;
  var h='<div class="slot'+(d?"":" empty")+'">';
  h+='<div class="sn">'+slotName(n)+'</div>';
  if(d){
    var an=(DATA.acts[d.act-1]||{}).name||"";
    var num=["","一","二","三","四","五","六"][d.act]||"";
    h+='<div class="si"><b>第'+num+'幕 · '+esc(d.pv||an)+'</b>';
    h+='<em>'+esc(an)+' · 决策 '+(d.decisions||0)+' 次 · 工时 '+(d.hours<=0?"超支":d.hours+"h")+' · '+fmtTime(d.ts)+'</em></div>';
    h+='<div class="sb"><button class="pri" data-act="loadslot" data-n="'+n+'">继续</button>';
    if(n!=="auto") h+='<button data-act="saveslot" data-n="'+n+'">覆盖</button>';
    h+='<button data-act="exportslot" data-n="'+n+'">导出</button>';
    h+='<button class="del" data-act="delslot" data-n="'+n+'">删除</button></div>';
  } else {
    h+='<div class="si"><b>空</b><em>把进度存到这里，方便回到某个节点重试</em></div>';
    h+='<div class="sb"><button data-act="saveslot" data-n="'+n+'">存到这里</button></div>';
  }
  return h+'</div>';
}
function viewSaves(){
  var h='<div class="saves-wrap">';
  h+='<div class="phase"><span class="p1">存 档</span><span class="p2">自动存档 + 三个手动位</span></div>';
  h+='<h2 class="ev-title">继续哪一次</h2>';
  h+='<div class="slots">';
  var list=slotList();
  for(var i=0;i<list.length;i++) h+=slotCard(list[i]);
  h+='</div>';
  h+='<div class="savetip">进度存在这台设备的浏览器里；换设备、清缓存会丢，重要节点建议「导出」成文件。<br>'
    + (STORE_OK ? '每次选择后会自动保存，随时关掉都能接着玩。'
                : '<b style="color:#B4593B">当前环境不允许写入本机存储，关掉页面会丢进度，请先导出。</b>')
    + '</div>';
  h+='<div class="saverow">';
  h+='<button class="btn-primary" data-act="newgame">开新的一局</button>';
  h+='<button class="btn-ghost" data-act="import">导入存档文件</button>';
  h+='<button class="btn-ghost" data-act="backfromsaves">回到游戏</button>';
  h+='</div></div>';
  return h;
}
function viewAch(){
  var h='<div class="saves-wrap" style="max-width:820px">';
  h+='<div class="phase"><span class="p1">成 就</span><span class="p2">'+achCount()+'</span></div>';
  h+='<h2 class="ev-title">做到了什么</h2>';
  h+=achWall(false);
  h+='<div class="savetip">成就跨周目累积，存在这台设备上，不随存档删除。稀有度：普通 / 稀有 / 极难。<br>灰色的是还没拿到的，提示就是线索。</div>';
  h+='<div class="saverow"><button class="btn-ghost" data-act="backfromsaves">回到游戏</button></div>';
  h+='</div>';
  return h;
}
function exportSlot(n){
  var d=slotRead(n);
  if(!d){ alert("这一格还没有存档。"); return; }
  var stamp=(function(){ var t=new Date(),p=function(v){return v<10?("0"+v):(""+v);};
    return t.getFullYear()+p(t.getMonth()+1)+p(t.getDate())+"-"+p(t.getHours())+p(t.getMinutes()); })();
  var blob=new Blob([JSON.stringify(d)],{type:"application/json"});
  var url=URL.createObjectURL(blob);
  var a=document.createElement("a");
  a.href=url; a.download="auditer-"+slotName(n)+"-"+stamp+".json";
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(function(){ URL.revokeObjectURL(url); }, 1500);
}
function importFile(file){
  var fr=new FileReader();
  fr.onload=function(){
    try{
      var o=JSON.parse(fr.result);
      if(!o || !o.act){ alert("这不是 AUDITER 的存档文件。"); return; }
      if(slotRead(1) && !confirm("存档 1 已有进度，覆盖吗？")) return;
      slotWrite(1,o);
      S._back="saves"; S.screen="saves"; render();
    }catch(e){ alert("存档文件读取失败：" + e.message); }
  };
  fr.readAsText(file);
}

function viewActIntro(){
  var a=actInfo(S.act);
  var NUM=["","一","二","三","四","五","六"];
  var h='<div class="act-intro">';
  if(a.bg){
    h+='<div class="act-hero"><img src="'+a.bg+'" alt="" onerror="this.parentNode.style.display=\'none\'"><div class="ah-ov"></div>';
    h+='<div class="ah-tx"><span class="ah-num">第 '+NUM[S.act]+' 幕 · ACT '+S.act+'</span><h2>'+esc(a.name)+'</h2><p>'+esc(a.sub)+'</p></div></div>';
  }else{
    h+='<div class="num">第 '+NUM[S.act]+' 幕</div>';
    h+='<h2>'+esc(a.name)+'</h2>';
    h+='<div class="sub">'+esc(a.sub)+'</div>';
  }
  if(a.quote) h+='<div class="quote">'+esc(a.quote)+'</div>';
  h+='<button class="btn-primary" data-act="begin">进入现场</button>';
  h+='</div>';
  return h;
}

function viewEvent(){
  var e=LIST[S.i]; if(!e) return "";
  var abg=actBg(), an=actInfo(S.act).name;
  var h='<div class="phase">'+(abg?'<span class="loc"><img src="'+abg+'" alt="" onerror="this.style.visibility=\'hidden\'">'+esc(an)+'</span>':'<span class="p1">'+esc(an)+'</span>')+'<span class="p2">'+esc(e.time||"")+'</span></div>';
  h+='<h2 class="ev-title">'+esc(e.title)+'</h2>';
  h+='<div class="prose">';
  for(var i=0;i<(e.text||[]).length;i++) h+='<p>'+e.text[i]+'</p>';
  if(e.dyn){ var dt=e.dyn(S); if(dt){ for(var dz=0;dz<dt.length;dz++) h+='<p>'+dt[dz]+'</p>'; } }
  h+='</div>';
  if(e.talk){
    var tid=crewIdByName(e.talk.who);
    h+='<div class="talk"><div class="t-side">'+avatarImg(tid,"t-av")+'<span class="who">'+esc(e.talk.who)+'</span></div>';
    h+='<div class="t-body">';
    for(var j=0;j<e.talk.lines.length;j++) h+='<p>'+e.talk.lines[j]+'</p>';
    h+='</div></div>';
  }
  if(e.cc){
    h+='<div class="ccrow'+(S.ccOn?" on":"")+'" data-act="cc"><span class="cbox">'+(S.ccOn?"✓":"")+'</span><span class="cct">'+esc(e.cc.label)+'</span><span class="ccn">抄了推得快，对方会记住</span></div>';
  }
  h+='<div class="opts">';
  var K=["A","B","C","D"];
  for(var c=0;c<e.choices.length;c++){
    var o=e.choices[c];
    h+='<button class="opt" data-act="choose" data-i="'+c+'"><span class="k">'+K[c]+'</span><span><span class="t">'+esc(o.t)+'</span>'+(o.sub?'<span class="sub">'+esc(o.sub)+'</span>':'')+'</span></button>';
  }
  h+='</div>';
  return h;
}

function viewResult(){
  var e=LIST[S.i]; if(!e) return "";
  var c=e.choices[S.chosen]; if(!c) return "";
  var r=S.lastResult||{};
  var abg=actBg(), an=actInfo(S.act).name;
  var h='<div class="phase">'+(abg?'<span class="loc"><img src="'+abg+'" alt="" onerror="this.style.visibility=\'hidden\'">'+esc(an)+'</span>':'<span class="p1">'+esc(an)+'</span>')+'<span class="p2">'+esc(e.time||"")+'</span></div>';
  h+='<h2 class="ev-title">'+esc(e.title)+'</h2>';
  h+='<div class="result">';
  if(r.mode) h+='<div class="said"><span class="lbl">你 说 的 是</span><q>'+esc(r.mode.line)+'</q></div>';
  if(r.delta && r.delta.length){
    h+='<div class="delta">';
    for(var i=0;i<r.delta.length;i++) h+='<span class="'+r.delta[i].k+'">'+esc(r.delta[i].t)+'</span>';
    h+='</div>';
  }
  h+='<p>'+esc(r.res||"")+'</p>';
  h+='</div>';
  if(r.note){ h+='<div class="note"><span class="tag">底 稿 批 注</span><p>'+r.note+'</p></div>'; }
  if(S.crewDelta){
    var cd="";
    for(var ck in S.crewDelta){
      if(!S.crewDelta.hasOwnProperty(ck)) continue;
      var dv=S.crewDelta[ck], cnm=S.crew[ck]?S.crew[ck].name:"";
      cd+='<span class="'+(dv>0?"up":"dn")+'">'+avatarImg(ck,"")+esc(cnm)+(dv>0?" 更愿意配合了":" 更不配合了")+'</span>';
    }
    if(cd) h+='<div class="crew-delta"><em>这件事之后，他们怎么看你</em>'+cd+'</div>';
  }
  if(S.newMeet && S.newMeet.length){
    var nm="";
    for(var q=0;q<S.newMeet.length;q++){ nm+=(q?", ":"")+S.crew[S.newMeet[q]].name; }
    h+='<div class="meet-tip">「'+esc(nm)+'」已记入人员名单。左侧能看见他怎么看你。</div>';
  }
  h+='<button class="cont" data-act="next">继续 <span class="mono" style="opacity:.5">↵</span></button>';
  return h;
}

function viewActEnd(){
  var d=S.lastDiff||{};
  var a=actInfo(S.act);
  var cs=companyState();
  var h='<div class="settle">';
  h+='<div class="phase"><span class="p1">阶 段 总 结</span><span class="p2">第 '+S.act+' 幕结束</span></div>';
  h+='<h2>'+esc(a.name)+' 落幕</h2>';
  h+='<p class="lead">'+(d.lead||"")+'</p>';
  /* 进度 */
  var pct=Math.round(S.act/6*100);
  var used=S.hours<=0?100:Math.round((1-S.hours/S.max)*100);
  h+='<div class="prog"><div class="pg-top"><span>第 '+S.act+' 幕 / 共 6 幕</span><b>'+pct+'%</b></div>';
  h+='<div class="pg-bar"><i style="width:'+pct+'%"></i></div>';
  h+='<p>'+esc(DATA.progress[S.act]||"")+'</p>';
  h+='<div class="pg-meta"><span>预算已用 '+used+'%</span><span>未了结事项 '+S.cards.length+' 项</span><span>已做判断 '+S.decisions+' 次</span></div>';
  h+='</div>';
  h+='<div class="ledger">';
  var rows=[["预算工时",d.hours],["其中：会议、往返、行政","−"+(d.overhead||0)+"h"],["团队精力",d.morale],["客户配合",d.client],["合伙人观感",d.partner],["风险欠账",d.risk]];
  for(var i=0;i<rows.length;i++){
    if(rows[i][1]==null) continue;
    h+='<div class="row"><span>'+rows[i][0]+'</span><b>'+rows[i][1]+'</b></div>';
  }
  h+='</div>';
  if(FIRED && FIRED.length){
    h+='<div class="fired"><span class="tag">到 期 的 牌</span>';
    for(var k=0;k<FIRED.length;k++) h+='<div class="item">'+FIRED[k].reveal+'</div>';
    h+='</div>';
  }

  /* 这一段你看见了什么 */
  var seen=[],blindNow=[];
  if(S.sigNews){
    for(var s=0;s<S.sigNews.length;s++){
      if(S.sigNews[s].seen) seen.push(S.sigNews[s].sig);
      else blindNow.push(S.sigNews[s].sig);
    }
  }
  if(seen.length){
    h+='<div class="sec"><div class="sec-lbl">这 一 段，你 看 清 了 什 么</div>';
    for(var t=0;t<seen.length;t++){
      var g=seen[t];
      h+='<div class="truth"><div class="tt"><span class="bd">'+esc(g.badge)+'</span>'+esc(g.title)+'</div>';
      h+='<p>'+g.body+'</p>';
      if(g.more) h+='<p class="more">'+g.more+'</p>';
      h+='</div>';
    }
    h+='</div>';
  }
  if(blindNow.length){
    h+='<div class="sec"><div class="sec-lbl">这 一 段，你 没 看 见 的</div>';
    h+='<div class="blind"><p>有 <b>'+blindNow.length+'</b> 件事，从你眼前过去了。你当时觉得没什么。</p>';
    h+='<p>它们不会当场出事。它们会在你签完字之后，以另一种方式回来——那时候你手上已经没有工时，也没有第二次机会。</p></div>';
    h+='</div>';
  }

  /* 公司状况——它一直在往坏的方向走，跟你努不努力无关 */
  h+='<div class="sec"><div class="sec-lbl">这 家 公 司，现 在 什 么 样</div>';
  h+='<div class="co"><div class="co-hd"><b>'+esc(cs.t)+'</b><span class="co-n">HX 精密 · 进场第 '+S.act+' 个月</span></div>';
  h+='<p>'+esc(cs.h)+'</p></div></div>';

  /* 每个人现在怎么看 */
  var ids=["zhou","xu","lin","li","wang","zhao"],att="";
  for(var p=0;p<ids.length;p++){
    var c=S.crew[ids[p]];
    if(!c||!c.met) continue;
    var line=attLine(ids[p]);
    if(line==null) continue;
    att+='<div class="att-row"><span class="an">'+avatarImg(ids[p],"")+esc(c.name)+'</span><span class="at">'+esc(line)+'</span></div>';
  }
  if(att) h+='<div class="sec"><div class="sec-lbl">他 们 现 在 怎 么 看 你</div>'+att+'</div>';

  /* 钩子 */
  var unk=DATA.unknown[S.act];
  if(unk) h+='<div class="unk"><span class="tag">你 还 不 知 道 的</span><p>'+esc(unk)+'</p></div>';

  h+='<div class="checkup"><span class="tag">风 险 体 检</span><p>'+S.checkup+'</p></div>';
  h+='<button class="cont" data-act="advance">往下走 <span class="mono" style="opacity:.5">↵</span></button>';
  h+='</div>';
  return h;
}

function memberName(m){
  if(m==="self") return "我自己";
  var c=S.crew[m];
  return c?c.name:"";
}
function memberLabel(m){
  if(m==="self") return avatarImg("self","")+'我自己<small>32h</small>';
  var c=S.crew[m];
  if(!c) return "";
  var sub="";
  if(c.skill!=null){
    sub = c.skillKnown ? ("能力 "+c.skill) : "能力 ?";
    if(c.energy!=null) sub += " · 精力 "+c.energy;
  }
  return avatarImg(m,"")+esc(c.name)+'<small>'+esc(sub)+'</small>';
}
function viewDispatch(){
  var d=DATA.dispatch[S.act];
  var h='<div class="dispatch">';
  h+='<div class="phase"><span class="p1">计 划</span><span class="p2">进场前 · 派工</span></div>';
  h+='<h2 class="ev-title">把活分下去</h2>';
  h+='<p style="font-size:14.5px;line-height:1.9;color:#55534B;margin:0 0 8px">'+esc(d.lead)+'</p>';
  h+='<p style="font-size:12.5px;color:#9A978C;line-height:1.7;margin:0 0 24px">'+esc(d.hint)+'</p>';
  for(var i=0;i<d.tasks.length;i++){
    var t=d.tasks[i], picked=S.pick[t.id];
    h+='<div class="dtask'+(picked?" done":"")+'">';
    h+='<div class="dt-head"><b>'+esc(t.name)+'</b><span class="diff">'+new Array(t.diff+1).join("●")+new Array(4-t.diff).join("○")+'</span></div>';
    h+='<p class="dt-desc">'+esc(t.desc)+'</p>';
    h+='<p class="dt-risk">'+esc(t.risk)+'</p>';
    h+='<div class="dt-opts">';
    for(var j=0;j<d.members.length;j++){
      var m=d.members[j];
      h+='<button class="dpick'+(picked===m?" on":"")+'" data-act="pick" data-t="'+t.id+'" data-m="'+m+'">'+memberLabel(m)+'</button>';
    }
    h+='</div></div>';
  }
  var all=true;
  for(var q=0;q<d.tasks.length;q++){ if(!S.pick[d.tasks[q].id]) all=false; }
  h+='<button class="cont" data-act="confirmDispatch"'+(all?"":' disabled style="opacity:.3;cursor:not-allowed"')+'>分完了，开始干活 <span class="mono" style="opacity:.5">↵</span></button>';
  h+='</div>';
  return h;
}
function viewDispatchResult(){
  var h='<div class="dispatch">';
  h+='<div class="phase"><span class="p1">计 划</span><span class="p2">活分完了</span></div>';
  h+='<h2 class="ev-title">账面上看不出区别</h2>';
  h+='<p style="font-size:13px;color:#8A887E;line-height:1.8;margin:0 0 20px">三个任务都分下去了。现在底稿看起来是一样的——完整、有签字、有索引。区别要过一段时间才会显出来。</p>';
  for(var i=0;i<S.dispatchResults.length;i++){
    var x=S.dispatchResults[i];
    h+='<div class="dres'+(x.bad?" bad":"")+'"><span class="who">'+esc(x.task)+' → '+avatarImg(x.member,"")+esc(memberName(x.member))+'</span><span class="t">'+esc(x.text)+'</span></div>';
  }
  h+='<button class="cont" data-act="afterDispatch">进场 <span class="mono" style="opacity:.5">↵</span></button>';
  h+='</div>';
  return h;
}
function confirmDispatch(){
  var d=DATA.dispatch[S.act];
  var out=[];
  for(var i=0;i<d.tasks.length;i++){
    var t=d.tasks[i], m=S.pick[t.id];
    var r=d.results[t.id+"_"+m];
    if(!r) continue;
    applyEff(r.eff);
    if(r.meter){
      for(var mid in r.meter){
        if(!S.crew[mid]||!r.meter.hasOwnProperty(mid)) continue;
        var mv=r.meter[mid];
        for(var k in mv){
          if(!mv.hasOwnProperty(k)) continue;
          if(k==="skill"){ S.crew[mid].skill=clamp(S.crew[mid].skill+mv[k],0,100); S.crew[mid].skillKnown=true; }
          else S.crew[mid][k]=clamp(S.crew[mid][k]+mv[k],0,100);
        }
      }
    }
    if(r.card){
      S.cards.push({id:r.card.id,label:r.card.label,trigger:r.card.trigger,
        severity:r.card.severity,reveal:r.card.reveal,eff:r.card.eff||{}});
    }
    out.push({task:t.name,member:m,text:r.text,bad:!!(r.card&&r.card.severity>=2)});
  }
  S.dispatchResults=out;
  S.dispatchDone=true;
  S.screen="dispatchResult"; save(); render();
}

/* 三年后。你当年看清了多少，决定了这段文字的长度。 */
function afterword(){
  var t=(S.truth||[]).length;
  var h='<div class="sec" style="margin-top:24px"><div class="sec-lbl">三 年 后</div>';
  var co;
  if(t>=4){
    co="调查组的问询记录里，你的名字出现了十一次。不是因为你说错了什么，是因为你当年在底稿里写下的每一句，后来都变成了索引——他们顺着你标过的位置，走到了所有该去的地方。你留下的东西既能证明他们的问题，也能证明你当时看见了。";
  }else if(t>=2){
    co="调查组调走了全部底稿。有些问题你当年写过，有些没写。你能解释的都解释了，解释不了的，用的是同一句话：当时信息不完整。这句话在记录里出现了四次。";
  }else{
    co="调查结论里有一句：「未见会计师对上述迹象保持应有的职业怀疑。」这句话不需要任何证据支撑——因为你什么都没有写。你签的字很整齐，底稿也很整齐，整齐得像从来没有人真的在那里待过九十天。";
  }
  var tag = t>=4 ? ("你看清了 "+t+" 件事") : (t>0 ? ("你看清了 "+t+" 件事，剩下的没看见") : "你什么都没看清");
  h+='<div class="co"><div class="co-hd"><b>HX 精密 · 后来</b><span class="co-n">'+esc(tag)+'</span></div><p>'+esc(co)+'</p></div>';

  var lin=S.crew.lin;
  if(lin && lin.met){
    var lt;
    if(lin.skill>=45 && lin.trust>=58){
      lt="他留了下来，第三年考出 CPA，第六年开始带自己的项目。他跟新人讲起第一年时，会提一句「我那时候发现过两张票，我师父让我把话说完」——他说的师父是你。";
    }else if(lin.skill>=45){
      lt="他留在所里，做得不错，两年后跳去了一家更大的所。你们偶尔在行业培训上碰见，点头，聊两句，没有再共事。";
    }else if(lin.skill>=32){
      lt="他做了两年，转去了客户那边做财务。他说审计太累，也说「那一年学到的东西，其实挺多的」。";
    }else{
      lt="他第二年就离开了这个行业。走之前把注会教材送给了同组的人，扉页上写着「先活着」。";
    }
    h+='<div class="co" style="margin-top:10px"><div class="co-hd"><b>小林 · 后来</b><span class="co-n">你带过的第一个实习生</span></div><p>'+esc(lt)+'</p></div>';
  }
  h+='</div>';
  return h;
}

/* ═══════ 成就（跨周目） ═══════ */
var META_KEY="auditer_meta_v1";
var META=(function(){
  try{
    var o=JSON.parse(sget(META_KEY)||"{}");
    if(!o || typeof o!=="object") o={};
    o.ach=o.ach||{}; o.endings=o.endings||{}; o.runs=o.runs||0; o.best=o.best||0;
    return o;
  }catch(e){ return {ach:{},endings:{},runs:0,best:0}; }
})();
function metaSave(){ sset(META_KEY, JSON.stringify(META)); }
function achById(id){
  for(var i=0;i<DATA.achievements.length;i++){ if(DATA.achievements[i].id===id) return DATA.achievements[i]; }
  return null;
}
var toastTimer=null;
function toast(txt){
  var el=$("toast");
  if(!el){ el=document.createElement("div"); el.id="toast"; el.className="toast"; document.body.appendChild(el); }
  el.innerHTML='<em>ACHIEVEMENT</em>'+esc(txt);
  el.classList.add("on");
  clearTimeout(toastTimer);
  toastTimer=setTimeout(function(){ el.classList.remove("on"); }, 3200);
}
function unlock(id){
  if(!id || META.ach[id]) return;
  var a=achById(id); if(!a) return;
  META.ach[id]=Date.now(); metaSave();
  if(S){ S.newAch=S.newAch||[]; if(S.newAch.indexOf(id)<0) S.newAch.push(id); }
  toast("成就解锁 · "+a.n);
}
function checkAch(){
  var A=DATA.achievements||[];
  for(var i=0;i<A.length;i++){
    var a=A[i];
    if(META.ach[a.id] || a.end) continue;
    if(a.id==="first"){ if((S.decisions||0)>=1) unlock("first"); continue; }
    if(a.id==="finish"){ if(S.screen==="ending") unlock("finish"); continue; }
    if(a.cond){ try{ if(a.cond(S)) unlock(a.id); }catch(e){} }
  }
}
function achWall(onlyUnlocked){
  var h='<div class="achgrid">';
  var arr=DATA.achievements||[];
  for(var i=0;i<arr.length;i++){
    var a=arr[i], on=!!META.ach[a.id];
    if(onlyUnlocked && !on) continue;
    var fr=(S.newAch||[]).indexOf(a.id)>=0;
    h+='<div class="ach'+(on?"":" lock")+(fr?" fresh":"")+'">';
    h+='<span class="rar">'+(a.r===3?"极难":(a.r===2?"稀有":"普通"))+'</span>';
    h+='<b>'+(on?esc(a.n):"？？？")+'</b>';
    h+='<em>'+(on?esc(a.d):("提示："+esc(a.h)))+'</em></div>';
  }
  return h+'</div>';
}
function achCount(){
  var n=0, arr=DATA.achievements||[];
  for(var i=0;i<arr.length;i++){ if(META.ach[arr[i].id]) n++; }
  return n+"/"+arr.length;
}

/* ═══════ 评分 / 分叉 / 战报 ═══════ */
function computeScore(){
  var un=NS_unresolved(S).length, so=NS_solved(S).length;
  var prof=clamp(100 - S.risk*0.9 + (S.truth||[]).length*5 - un*3 + so*2, 0, 100);
  var riskc=clamp(100 - S.risk + (S.punish===0?30:0) - (S.punish||0)*8, 0, 100);
  var ce=0,n=0;
  for(var k in S.crew){ if(S.crew.hasOwnProperty(k) && S.crew[k].met){ ce+=S.crew[k].trust||0; n++; } }
  ce = n ? (ce/n) : 0;
  var rel=clamp((S.partner + S.client + ce)/3, 0, 100);
  var eff=clamp((S.hours/Math.max(1,S.max))*60 + (S.client>=55?20:0) + (S.hours>0?20:0), 0, 100);
  var total=Math.round(prof*0.35 + riskc*0.30 + rel*0.20 + eff*0.15);
  var grade = total>=85?"S":(total>=72?"A":(total>=58?"B":(total>=42?"C":"D")));
  return {prof:Math.round(prof),risk:Math.round(riskc),rel:Math.round(rel),eff:Math.round(eff),
          total:total,grade:grade,un:un,so:so};
}
function findEventByTitle(t){
  for(var i=0;i<DATA.events.length;i++){ if(DATA.events[i].title===t) return DATA.events[i]; }
  return null;
}
function forks(){
  var out=[], L=S.log||[];
  for(var i=0;i<L.length;i++){
    var l=L[i]; if(typeof l.i!=="number") continue;
    var ev=findEventByTitle(l.title); if(!ev) continue;
    var mine=ev.choices[l.i]; if(!mine) continue;
    var mineSev=0; (mine.cards||[]).forEach(function(c){ mineSev=Math.max(mineSev,c.severity||0); });
    if(mineSev<2) continue;
    /* 另一条路：在剩下的选项里找「最大后果更轻」的那一条 */
    var alt=null, altSev=99;
    for(var j=0;j<ev.choices.length;j++){
      if(j===l.i) continue;
      var s=0; (ev.choices[j].cards||[]).forEach(function(c){ s=Math.max(s,c.severity||0); });
      if(s<altSev){ altSev=s; alt=ev.choices[j]; }
    }
    if(!alt || altSev>=mineSev) continue;
    out.push({t:ev.title, mine:mine.t, alt:alt.t, altRes:(alt.res||"").split("。")[0]+"。"});
  }
  return out.slice(0,3);
}
function endingKey(){
  for(var k in DATA.endings){ if(DATA.endings.hasOwnProperty(k) && DATA.endings[k]===S.ending) return k; }
  return "";
}
function reportText(){
  var sc=computeScore(), E=S.ending;
  var hz=S.hours<=0 ? "超支" : (Math.round(S.hours/S.max*100)+"%");
  var t=[];
  t.push("AUDITER · 一个项目经理的 90 天");
  t.push("结局："+E.title);
  t.push("评级："+sc.grade+"（"+sc.total+"）｜决定 "+S.decisions+" 次｜看清 "+(S.truth||[]).length+"/5 件事｜未了结 "+S.cards.length+" 张牌");
  t.push("预算剩 "+hz+"｜团队 "+S.morale+"｜客户 "+S.client+"｜合伙人 "+S.partner);
  return t.join("\n");
}

function viewEnding(){
  var E=S.ending;
  var sc=computeScore();
  var h='<div class="ending">';
  if(DATA.acts[5]&&DATA.acts[5].bg){
    h+='<div class="act-hero slim"><img src="'+DATA.acts[5].bg+'" alt="" onerror="this.parentNode.style.display=\'none\'"><div class="ah-ov"></div></div>';
  }
  h+='<div class="eyebrow">'+esc(E.eyebrow||"项 目 结 案")+'</div>';
  h+='<h2>'+esc(E.title)+'</h2>';
  h+='<div class="desc">'+esc(E.desc)+'</div>';
  h+='<div class="verdict">'+esc(E.verdict)+'</div>';

  /* 1. 评分卡 */
  var dims=[["专业判断",sc.prof],["风险控制",sc.risk],["关系资本",sc.rel],["经营效率",sc.eff]];
  var sorted=dims.slice().sort(function(a,b){ return b[1]-a[1]; });
  var best=sorted[0], worst=sorted[3];
  var col=function(v){ return v>=72?"#2B6B57":(v>=58?"#9A6F32":(v>=42?"#B0783C":"#B4593B")); };
  h+='<div class="score">';
  h+='<div class="sc-hd"><b>结 算</b><span class="sc-grade">'+sc.grade+'</span></div>';
  h+='<div class="sc-total"><em>'+sc.total+'</em><i>/ 100 综合评级<br>不含结局判定，仅供复盘</i></div>';
  for(var i=0;i<dims.length;i++){
    h+='<div class="sc-row"><span>'+dims[i][0]+'</span><div class="bar"><i style="width:'+dims[i][1]+'%;background:'+col(dims[i][1])+'"></i></div><b>'+dims[i][1]+'</b></div>';
  }
  h+='<div class="sc-note">你最强的一块是<b>'+best[0]+'</b>（'+best[1]+'），最弱的是<b>'+worst[0]+'</b>（'+worst[1]+'）。'+
     (worst[1]<58 ? '这一块，是下一次可以专门练的。' : '整体没有明显短板——这在这个项目里很少见。')+'</div>';
  h+='</div>';

  /* 2. 关键分叉 */
  var fk=forks();
  if(fk.length){
    h+='<div class="sec" style="margin-top:24px"><div class="sec-lbl">关 键 分 叉</div>';
    for(var f=0;f<fk.length;f++){
      h+='<div class="fork"><b>'+esc(fk[f].t)+'</b>';
      h+='<div class="f-row"><span class="f-lbl">你选的</span>'+esc(fk[f].mine)+'</div>';
      h+='<div class="f-row f-alt"><span class="f-lbl">另一条路</span>'+esc(fk[f].alt)+'——'+esc(fk[f].altRes)+'</div>';
      h+='</div>';
    }
    h+='</div>';
  }

  /* 3. 账本 */
  var un=NS_unresolved(S), so=NS_solved(S);
  h+='<div class="ledger">';
  h+='<div class="row"><span>看清了几件事</span><b>'+(S.truth||[]).length+' / 5</b></div>';
  h+='<div class="row"><span>未了结的牌</span><b>'+S.cards.length+' 张</b></div>';
  h+='<div class="row"><span>踩过线的次数</span><b>'+S.punish+'</b></div>';
  h+='<div class="row"><span>预算执行</span><b>'+(S.hours<=0?"已超支":(Math.round(S.hours/S.max*100)+"% 剩余"))+'</b></div>';
  h+='</div>';
  if(so.length){
    h+='<div class="checkup" style="margin-top:16px"><span class="tag">你 做 实 的</span><p>'+esc(so.slice(0,6).join("、"))+(so.length>6?("，等 "+so.length+" 项。"):"。")+'</p></div>';
  }
  if(un.length){
    h+='<div class="checkup" style="margin-top:10px"><span class="tag" style="color:#B4593B">你 放 过 的</span><p>'+esc(un.join("；"))+'。</p></div>';
  }

  /* 4. 战报 */
  h+='<div class="report"><div class="rp-hd">战 报 · 可 复 制</div>'+esc(reportText())+'</div>';
  h+='<button class="btn-copy" data-act="copyreport">复制战报</button>';

  if(E.advice){ h+='<div class="checkup" style="margin-top:20px"><span class="tag">如 果 重 来</span><p>'+esc(E.advice)+'</p></div>'; }
  h+=afterword();

  /* 5. 成就 */
  var got=0, total=(DATA.achievements||[]).length;
  for(var ai=0;ai<total;ai++){ if(META.ach[DATA.achievements[ai].id]) got++; }
  h+='<div class="sec" style="margin-top:26px"><div class="sec-lbl">成 就 · '+got+' / '+total+'</div>';
  if(got){
    h+=achWall(true);
    h+='<div class="savetip">'+(total-got>0?('还有 '+(total-got)+' 个没拿到，提示都在成就页里。'):'全部成就已达成。')+'</div>';
  } else {
    h+='<div class="savetip">这一轮一个成就都没解锁——下一轮换个打法试试。<br>提示：该去的地方亲自去，该说的话当面说。</div>';
  }
  h+='<button class="btn-ghost" data-act="ach" style="margin-top:10px">查看全部成就</button>';
  h+='</div>';

  h+='<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:22px">';
  h+='<button class="cont" data-act="restart">再走一次</button>';
  h+='<button class="btn-ghost" data-act="saves">存档 / 换一局</button>';
  h+='<button class="btn-ghost" data-act="toTitle">回到标题</button>';
  h+='</div>';
  h+='</div>';
  return h;
}

function applyEff(eff){
  if(!eff) return [];
  var out=[], names={hours:"工时",morale:"团队",client:"客户",partner:"合伙人",risk:"风险"};
  for(var k in eff){
    if(!eff.hasOwnProperty(k)) continue;
    var v=eff[k]; if(!v) continue; var shown=v;
    if(k==="hours"){ S.hours=Math.max(0,S.hours+v); }
    else if(k==="risk"){ S.risk=clamp(S.risk+v,0,100); }
    else if(k==="partner"){ shown=Math.round(v*0.55); S.partner=clamp(S.partner+shown,0,100); if(!shown) continue; }
    else if(k==="morale"||k==="client"){ S[k]=clamp(S[k]+v,0,100); }
    else if(k==="ms"){ S.ms+=v; }
    var label=(shown>0?"+":"")+shown+" "+names[k];
    var good = (k==="risk") ? v<0 : (v>0);
    out.push({t:label,k:good?"up":"dn"});
  }
  return out;
}

function choose(idx){
  var e=LIST[S.i]; var o=e.choices[idx];
  if(o.say && e.say){ S.pending=idx; S.screen="say"; save(); render(); return; }
  applyChoice(idx,null);
}

function applyChoice(idx,mode){
  var e=LIST[S.i]; var o=e.choices[idx];
  S.chosen=idx; S.decisions++;
  var delta=applyEff(o.eff);
  if(mode && mode.eff){ delta=delta.concat(applyEff(mode.eff)); }
  var ccTxt="";
  if(S.ccOn && e.cc){
    delta=delta.concat(applyEff(e.cc.eff||{}));
    ccTxt=e.cc.tail||"";
    if(e.cc.meter){
      for(var ck in e.cc.meter){
        if(!e.cc.meter.hasOwnProperty(ck)) continue;
        var ccg=S.crew[ck]; if(ccg) ccg.trust=clamp(ccg.trust+e.cc.meter[ck],0,100);
      }
    }
  }
  S.ccOn=false;
  S.morale=clamp(S.morale-1,0,100);
  if(o.flag){ for(var k in o.flag){ if(o.flag.hasOwnProperty(k)) S.flags[k]=o.flag[k]; } }
  if(o.cards){
    for(var i=0;i<o.cards.length;i++){
      var cd=o.cards[i];
      S.cards.push({id:cd.id,label:cd.label,trigger:cd.trigger,severity:cd.severity||1,
                    reveal:cd.reveal,eff:cd.eff||{},mark:cd.mark||""});
    }
  }
  if(o.punish) S.punish++;
  S.log.push({act:S.act,title:e.title,choice:o.t,idx:idx,i:idx,tag:o.tag||""});
  if(o.ach) unlock(o.ach);
  S.newMeet=[];
  if(e.meet){
    for(var mi=0;mi<e.meet.length;mi++){
      var cid=e.meet[mi];
      if(S.crew[cid] && !S.crew[cid].met){ S.crew[cid].met=true; S.newMeet.push(cid); }
    }
  }
  /* 把选项自带的和「怎么说」带来的关系变化合并结算 */
  var meters={};
  if(o.meter){ for(var m1 in o.meter){ if(o.meter.hasOwnProperty(m1)) meters[m1]=(meters[m1]||0)+o.meter[m1]; } }
  if(mode && mode.meter){ for(var m2 in mode.meter){ if(mode.meter.hasOwnProperty(m2)) meters[m2]=(meters[m2]||0)+mode.meter[m2]; } }
  S.crewDelta=null;
  var hasM=false;
  for(var mk in meters){ if(meters.hasOwnProperty(mk)) hasM=true; }
  if(hasM){
    S.crewDelta={};
    for(var mq in meters){
      if(!meters.hasOwnProperty(mq)) continue;
      var mc=S.crew[mq];
      if(!mc) continue;
      mc.trust=clamp(mc.trust+meters[mq],0,100);
      S.crewDelta[mq]=meters[mq];
    }
  }
  var res=o.res||"";
  if(mode && mode.tail) res=res+" "+mode.tail;
  if(ccTxt) res=res+" "+ccTxt;
  S.lastResult={delta:delta,res:res,note:o.note,mode:mode||null};
  S.pending=null;
  checkAch();
  S.screen="result"; save(); render();
}

function viewSay(){
  var e=LIST[S.i]; if(!e || !e.say) return "";
  var o=e.choices[S.pending]; if(!o) return "";
  var sy=e.say;
  var tid=crewIdByName(sy.to);
  var h='<div class="saywrap">';
  h+='<div class="phase"><span class="p1">沟 通</span><span class="p2">就差最后一句</span></div>';
  h+='<div class="saychosen"><span class="lbl">你已经决定</span>'+esc(o.t)+'</div>';
  if(tid||DATA.selfAvatar){
    h+='<div class="saypeers">'+avatarImg("self","sp-av")+'<span class="sp-arrow">→</span>'+(tid?avatarImg(tid,"sp-av"):'<span class="sp-av" style="display:inline-grid;place-items:center;background:#E8E4D8">?</span>')+'<span class="sp-name">'+esc(sy.to)+'</span></div>';
  }
  h+='<p class="sayprompt">'+esc(sy.prompt)+'</p>';
  h+='<div class="saymodes">';
  for(var i=0;i<sy.modes.length;i++){
    var m=sy.modes[i];
    h+='<button class="saym" data-act="say" data-i="'+i+'">';
    h+='<span class="sm-k">'+esc(m.t)+'</span>';
    h+='<span class="sm-line">'+esc(m.line)+'</span>';
    h+='</button>';
  }
  h+='</div>';
  h+='<p class="sayhint">对'+esc(sy.to)+'说。说出来之后，就收不回了。</p>';
  h+='</div>';
  return h;
}

function next(){
  S.newMeet=[];
  S.crewDelta=null;
  S.ccOn=false;
  S.pending=null;
  S.i++;
  if(S.i>=LIST.length){ endAct(); return; }
  S.screen="event"; save(); render();
}

/* ═══════ 暗线：这条消息你看不看得见，取决于你之前做了什么 ═══════ */
function signalSeen(sig){
  var i,c;
  if(sig.id==="sig1"){
    if(S.risk<=8) return true;
    for(i=0;i<(S.log||[]).length;i++){
      if(String(S.log[i].choice||"").indexOf("去年的底稿")>=0) return true;
    }
    return false;
  }
  if(sig.id==="sig2") return S.risk<=10;
  if(sig.id==="sig3"){
    for(i=0;i<(S.cards||[]).length;i++){
      c=S.cards[i];
      if(c.id==="rev_lin") return false;   /* 抽的全是 11 月，你根本没看到 12 月 */
      if(c.id==="conf_lin") return false;
    }
    return S.risk<=18;
  }
  if(sig.id==="sig4") return S.risk<=30;
  if(sig.id==="sig5") return S.risk<=42;
  return S.risk<=40;
}

function evalSignals(){
  var news=[];
  for(var i=0;i<DATA.signals.length;i++){
    var sig=DATA.signals[i];
    if(sig.act!==S.act) continue;
    if(S.seenSig.indexOf(sig.id)>=0) continue;
    S.seenSig.push(sig.id);
    if(signalSeen(sig)){
      S.truth.push({id:sig.id,title:sig.title,badge:sig.badge,body:sig.body,more:sig.more,key:sig.key});
      news.push({seen:true,sig:sig});
    }else{
      /* 没看见这件事，不是「当场扣分」，是三年后有人替你翻出来。
         所以它的严重度降一级入档，风险敞口照算。 */
      S.cards.push({id:sig.id,label:sig.blindLabel,trigger:sig.trigger,
        severity:Math.max(2,sig.severity-1),reveal:sig.blindReveal,eff:sig.blindEff||{},mark:"blind"});
      news.push({seen:false,sig:sig});
    }
  }
  return news;
}

/* 公司状况：跟你做了什么无关，它自己一直在往坏的方向走。
   差别只在于——你看清了没有。 */
function calcHealth(){
  var dmg=0;
  for(var i=0;i<DATA.signals.length;i++){
    if(DATA.signals[i].act<=S.act) dmg+=DATA.signals[i].damage;
  }
  return clamp(78-dmg-(S.act-1)*2,0,100);
}
function companyState(){
  var hp=S.health;
  for(var i=0;i<DATA.company.length;i++){
    var c=DATA.company[i];
    if(hp>=c.min) return {t:c.t,h:(S.truth.length>=3?c.hc:c.h)};
  }
  var l=DATA.company[DATA.company.length-1];
  return {t:l.t,h:l.h};
}
function attLine(id){
  var c=S.crew[id];
  if(!c||!c.met) return null;
  var v=(id==="li")?(c.coop!=null?c.coop:c.trust):c.trust;
  var arr=DATA.attitude[id]||[];
  for(var i=0;i<arr.length;i++){ if(v>=arr[i][0]) return arr[i][1]; }
  return "";
}

function endAct(){
  S.sigNews=evalSignals();
  FIRED=[];
  var keep=[];
  for(var i=0;i<S.cards.length;i++){
    var c=S.cards[i];
    if(c.trigger===S.act){ FIRED.push(c); }
    else keep.push(c);
  }
  S.cards=keep;
  for(var j=0;j<FIRED.length;j++){
    applyEff(FIRED[j].eff);
    if(FIRED[j].severity>=3 && FIRED[j].mark!=="blind") S.punish++;
  }
  var overhead=[0,38,46,54,62,72,84][S.act]||38;
  S.hours=Math.max(0,S.hours-overhead);
  S.client=clamp(Math.round(S.client+(50-S.client)*0.18),0,100);
  if(S.crew.wang && S.crew.wang.met && S.crew.wang.trust<32) S.risk=clamp(S.risk+3,0,100);
  if(S.crew.zhao && S.crew.zhao.met && S.crew.zhao.trust<26) S.hours=Math.max(0,S.hours-10);
  var big=0;
  for(var q=0;q<FIRED.length;q++){ if(FIRED[q].severity>=3 && FIRED[q].mark!=="blind") big++; }
  /* 老周真正在意的是「你有没有看见别人没看见的东西」。
     看清一件事，比少扣一张牌更值钱。 */
  var seenNow=0;
  if(S.sigNews){ for(var sn=0;sn<S.sigNews.length;sn++){ if(S.sigNews[sn].seen) seenNow++; } }
  if(seenNow>0) S.partner=clamp(S.partner+seenNow*6,0,100);
  if(big===0) S.partner=clamp(S.partner+3,0,100);
  if(S.hours>0) S.partner=clamp(S.partner+3,0,100);
  if(S.client>=50) S.partner=clamp(S.partner+2,0,100);
  if(S.risk>75) S.partner=clamp(S.partner-4,0,100);
  if(S.hours<=0){ S.morale=clamp(S.morale-4,0,100); }
  var d={};
  d.overhead=overhead;
  d.hours = (S.hours-SNAP.hours>=0?"+":"")+(S.hours-SNAP.hours)+"h";
  d.morale = (S.morale-SNAP.morale>=0?"+":"")+(S.morale-SNAP.morale);
  d.client = (S.client-SNAP.client>=0?"+":"")+(S.client-SNAP.client);
  d.partner = (S.partner-SNAP.partner>=0?"+":"")+(S.partner-SNAP.partner);
  d.risk = (S.risk-SNAP.risk>=0?"+":"")+(S.risk-SNAP.risk);
  d.lead = diffLead(d);
  S.lastDiff=d;
  S.health=calcHealth();
  S.checkup=checkupText();
  S.screen="actEnd";
  checkAch();
  save(); render();
}

function diffLead(d){
  if(S.hours<=0) return "预算已经见底了。后面每一小时都要从别的地方挪。";
  if(parseInt(d.risk,10)>18) return "这一段的账看着还行，但有几笔是记在后面的。";
  return "进度按计划走，账面上没什么好说的。";
}

function checkupText(){
  var r=S.risk, n=S.cards.length;
  if(r<18 && n===0) return "底稿干净。该函的函了，该盘的盘了，剩下的都是判断问题，不是程序问题。";
  if(r<18) return "程序上没留缺口，但还有 "+n+" 件事悬着，你自己知道是哪几件。";
  if(r<38) return "有几处用了替代程序，理由写在底稿上——写得过去，但如果被追问细节，你需要想一下。";
  if(r<58) return "质控如果抽到这个项目，会先看那几页。你已经不太愿意主动提起它们了。";
  if(r<78) return "欠的东西开始连成片。现在补还来得及，代价是预算和客户的脸色。";
  return "如果这个项目今天被抽中，你手上没有能挡住问题的东西。";
}

function computeEnding(){
  var E=DATA.endings;
  var severe=S.punish;
  var over = S.hours<=0;
  var pick;
  var path=(S.flags&&S.flags.path)||"";
  if(severe>=4) pick=E.punished;
  else if(S.morale<=16) pick=E.burnout;
  else if(S.partner<=8) pick=E.fired;
  else if(path==="qc" && S.risk<=52 && severe<=1) pick=E.tech;
  else if(path==="big" && S.partner>=45 && S.risk<=40) pick=E.partner;
  else if(S.client>=72 && S.risk>=52 && S.partner<70) pick=E.cfo;
  else if(S.partner>=55 && S.risk<=24 && severe===0 && S.client>=18) pick=E.partner;
  else if(S.partner>=42 && S.risk<=48) pick=E.tech;
  else if(S.risk<=42) pick=E.plain;
  else pick=E.drift;
  return pick;
}

function advance(){
  if(S.act>=6){ finish(); return; }
  startAct(S.act+1);
}

function startAct(n){
  S.act=n; S.i=0;
  if(n===2){ S.dispatchDone=false; S.pick={}; }
  SNAP={hours:S.hours,morale:S.morale,client:S.client,partner:S.partner,risk:S.risk};
  buildList(); S.screen="actIntro"; save(); render();
}

function begin(){
  if(DATA.dispatch && DATA.dispatch[S.act] && !S.dispatchDone){
    S.screen="dispatch"; S.pick={}; save(); render(); return;
  }
  S.screen="event"; S.i=0; buildList(); render();
}

function finish(){
  S.ending=computeEnding();
  var key=endingKey();
  if(key){
    META.endings[key]=(META.endings[key]||0)+1;
    META.runs=(META.runs||0)+1;
    var sc=computeScore();
    if(sc.total>(META.best||0)) META.best=sc.total;
    metaSave();
    unlock("e_"+key);
  }
  S.newAch=S.newAch||[];
  S.screen="ending";
  checkAch();
  save(); render();
}

function normalizeState(){
  if(!S.crew) S.crew=initCrew();
  else {
    var base=initCrew();
    for(var ck in base){ if(base.hasOwnProperty(ck) && !S.crew[ck]) S.crew[ck]=base[ck]; }
  }
  if(!S.pick) S.pick={};
  if(!S.newMeet) S.newMeet=[];
  if(!S.truth) S.truth=[];
  if(!S.seenSig) S.seenSig=[];
  if(S.ccOn==null) S.ccOn=false;
  if(S.health==null || isNaN(S.health)) S.health=calcHealth();
  if(S.dispatchDone==null) S.dispatchDone=false;
  SNAP={hours:S.hours,morale:S.morale,client:S.client,partner:S.partner,risk:S.risk};
  buildList();
  /* 任何屏幕都能安全恢复：把回不去的状态退到一个能玩的位置 */
  if(S.screen==="title") S.screen="actIntro";
  if(S.screen==="saves") S.screen=S._back||"actIntro";
  if(S.screen==="ach") S.screen=S._back||"actIntro";
  if(S.screen==="dispatch" && !(DATA.dispatch && DATA.dispatch[S.act])) S.screen="actIntro";
  if(S.screen==="dispatchResult") S.screen="dispatch";
  if(S.screen==="say" && (S.pending==null || !LIST[S.i])) S.screen="event";
  if(S.screen==="result" && (typeof S.chosen!=="number" || !LIST[S.i])) S.screen="event";
  if(S.screen==="event" && !LIST[S.i]){ S.i=0; S.screen="actIntro"; }
  if(S.screen==="ending" && !S.ending) S.ending=computeEnding();
}

function resumeFrom(state){
  if(!state) return;
  S=JSON.parse(JSON.stringify(state));
  normalizeState();
  save(); render();
}

function start(cont){
  if(cont){ var s=load(); S = s || fresh(); }
  else { S=fresh(); }
  normalizeState();
  save(); render();
}

document.addEventListener("click",function(ev){
  var el=ev.target.closest("[data-act]");
  if(!el) return;
  var a=el.getAttribute("data-act");
  if(a==="start"){ start(false); }
  else if(a==="resume"){ start(true); }
  else if(a==="saves"){ S._back=(S.screen==="title")?"title":S.screen; S.screen="saves"; render(); }
  else if(a==="ach"){ S._back=(S.screen==="title")?"title":S.screen; S.screen="ach"; render(); }
  else if(a==="toTitle"){ S.screen="title"; render(); }
  else if(a==="copyreport"){
    var txt=reportText();
    var done=function(){ toast("战报已复制"); };
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(txt).then(done, function(){
        prompt("复制下面的战报（Ctrl+C）：", txt);
      });
    } else {
      prompt("复制下面的战报（Ctrl+C）：", txt);
    }
  }
  else if(a==="backfromsaves"){
    if(S._back==="title"||!S._back){ S.screen="title"; render(); }
    else { S.screen=S._back; normalizeState(); render(); }
  }
  else if(a==="loadslot"){
    var sd=slotRead(el.getAttribute("data-n"));
    if(!sd){ alert("这一格是空的。"); return; }
    if(!confirm("载入这个存档？当前未保存的进度会被覆盖。")) return;
    resumeFrom(sd);
  }
  else if(a==="saveslot"){
    var sn=el.getAttribute("data-n");
    if(sn==="auto") return;
    if(!S._back || S._back==="title"){ alert("先开始或继续一局，再存到这个位置。"); return; }
    if(slotRead(sn) && !confirm("存档 "+sn+" 已有进度，覆盖吗？")) return;
    var cp=JSON.parse(JSON.stringify(S));
    cp.screen=S._back;
    slotWrite(sn,cp);
    render();
  }
  else if(a==="delslot"){
    var dn=el.getAttribute("data-n");
    if(!confirm("删除「"+slotName(dn)+"」的存档？删了就找不回来了。")) return;
    slotDel(dn); render();
  }
  else if(a==="exportslot"){ exportSlot(el.getAttribute("data-n")); }
  else if(a==="import"){ $("impSave").click(); }
  else if(a==="newgame"){
    if(!confirm("开新的一局？当前的自动存档会被新的进度覆盖（手动位不受影响）。")) return;
    sdel(LS); S=fresh(); S.screen="actIntro"; normalizeState(); save(); render();
  }
  else if(a==="begin"){ begin(); }
  else if(a==="choose"){ choose(parseInt(el.getAttribute("data-i"),10)); }
  else if(a==="say"){ var m=LIST[S.i].say.modes[parseInt(el.getAttribute("data-i"),10)]; applyChoice(S.pending,m); }
  else if(a==="cc"){ S.ccOn=!S.ccOn; save(); render(); }
  else if(a==="next"){ next(); }
  else if(a==="advance"){ advance(); }
  else if(a==="pick"){ S.pick[el.getAttribute("data-t")]=el.getAttribute("data-m"); save(); render(); }
  else if(a==="confirmDispatch"){ confirmDispatch(); }
  else if(a==="afterDispatch"){ S.screen="event"; S.i=0; buildList(); save(); render(); }
  else if(a==="restart"){ localStorage.removeItem(LS); S=fresh(); start(false); }
});

(function(){
  var imp=$("impSave");
  if(imp) imp.addEventListener("change",function(){
    if(this.files && this.files[0]) importFile(this.files[0]);
    this.value="";
  });
})();

document.addEventListener("keydown",function(ev){
  if(!S) return;
  var k=ev.key.toUpperCase();
  if(S.screen==="event" && "ABCD".indexOf(k)>=0){
    var i="ABCD".indexOf(k);
    if(LIST[S.i] && LIST[S.i].choices[i]) choose(i);
  }
  if(S.screen==="say" && "123".indexOf(ev.key)>=0){
    var si="123".indexOf(ev.key);
    var sy=LIST[S.i] && LIST[S.i].say;
    if(sy && sy.modes[si]) applyChoice(S.pending,sy.modes[si]);
    return;
  }
  if(ev.key==="Enter"){
    if(S.screen==="result") next();
    else if(S.screen==="actEnd") advance();
    else if(S.screen==="actIntro") begin();
  }
});

/* 预加载全部场景与头像，避免切换时闪白 */
(function(){
  var urls=[];
  for(var i=0;i<DATA.acts.length;i++){ if(DATA.acts[i].bg) urls.push(DATA.acts[i].bg); }
  for(var k in DATA.crew){ if(DATA.crew.hasOwnProperty(k)&&DATA.crew[k].avatar) urls.push(DATA.crew[k].avatar); }
  if(DATA.selfAvatar) urls.push(DATA.selfAvatar);
  for(var u=0;u<urls.length;u++){ (function(src){ var im=new Image(); im.src=src; })(urls[u]); }
})();

function autoplay(){
  start(false);
  var guard=0;
  try{
    while(S.screen!=="ending" && guard<600){
      guard++;
      if(S.screen==="title"||S.screen==="actIntro"){ S.screen="actIntro"; begin(); }
      else if(S.screen==="dispatch"){
        var D=DATA.dispatch[S.act];
        if(D){ for(var t=0;t<D.tasks.length;t++){ S.pick[D.tasks[t].id]=D.members[t%D.members.length]; } confirmDispatch(); }
        else { S.screen="event"; }
      }
      else if(S.screen==="dispatchResult"){ S.screen="event"; S.i=0; buildList(); }
      else if(S.screen==="event"){
        var e=LIST[S.i];
        if(!e){ S.screen="actIntro"; advance(); continue; }
        choose(Math.floor(Math.random()*e.choices.length));
      }
      else if(S.screen==="say"){ applyChoice(S.pending, LIST[S.i].say.modes[0]); }
      else if(S.screen==="result"){ next(); }
      else if(S.screen==="actEnd"){ advance(); }
      else break;
    }
  }catch(err){ console.error("autoplay", err); }
}

/* 调试入口：?boot=actIntro|event|dispatch&act=N 可直达某界面，正常游玩不受影响 */
S=fresh();
(function(){
  try{
    var q=new URLSearchParams(location.search);
    if(q.get("boot")==="resume"){ start(true); return; }
    if(q.get("boot")==="autoplay"){ autoplay(); render(); return; }
    if(q.get("boot")){
      S.screen=q.get("boot");
      if(q.get("act")) S.act=parseInt(q.get("act"),10)||1;
      if(q.get("hours")) S.hours=parseInt(q.get("hours"),10);
      if(q.get("risk")!=null) S.risk=parseInt(q.get("risk"),10);
      if(q.get("met")==="all"){ for(var k in S.crew){ S.crew[k].met=true; } }
      SNAP={hours:S.hours,morale:S.morale,client:S.client,partner:S.partner,risk:S.risk};
      if(S.screen==="event"||S.screen==="actIntro"||S.screen==="dispatch") buildList();
      if(S.screen==="saves") S._back="title";
    }
  }catch(e){}
  render();
})();
})();
